template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 60mm;
  height: 40mm;
  padding: 2.4mm 2.6mm 2mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 12px;
  font-weight: 700;
  line-height: 1.15;
  max-height: 2.3em;
  overflow: hidden;
}
.price {
  margin-top: 1.2mm;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
}
.price-main {
  font-size: 24px;
}
.price-tail {
  font-size: 15px;
}
.currency {
  font-size: 11px;
  margin-left: 1.2mm;
  font-weight: 700;
}
.meta {
  font-size: 8px;
  margin-top: 0.8mm;
  color: #444;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.45mm;
  margin-top: auto;
  width: 100%;
}
.code {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
}
img.barcode {
  height: 13mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
